'use client';

import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { useReducedMotion } from './use-reduced-motion';
import './route-transition-curtain.css';

export interface CurtainView {
  id: string;
  title: string;
  content: ReactNode;
}

export interface RouteTransitionCurtainProps {
  views: CurtainView[];
  current: string;
  onNavigate: (id: string) => void;
  label: string;
  className?: string;
}

const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? useEffect : useLayoutEffect;

const HALF = 220;

/**
 * Changing view draws a curtain across, swaps the view behind it, then
 * draws it away. Rapid clicks simply retarget the swap. Focus lands on the
 * new view's heading so keyboard and screen-reader users know where they are.
 */
export function RouteTransitionCurtain({
  views,
  current,
  onNavigate,
  label,
  className = '',
}: RouteTransitionCurtainProps) {
  const [shown, setShown] = useState(current);
  const [phase, setPhase] = useState<'idle' | 'cover' | 'reveal'>('idle');
  const target = useRef(current);
  const timer = useRef(0);
  const moved = useRef(false);
  const heading = useRef<HTMLHeadingElement>(null);
  const reduced = useReducedMotion();
  const titleId = useId();

  useEffect(() => {
    target.current = current;
    if (current === shown && phase === 'idle') return;
    moved.current = true;
    if (reduced) {
      setShown(current);
      return;
    }
    if (phase === 'cover') return; // the swap at mid-point will pick up the new target
    window.clearTimeout(timer.current);
    setPhase('cover');
    timer.current = window.setTimeout(() => {
      setShown(target.current);
      setPhase('reveal');
      timer.current = window.setTimeout(() => setPhase('idle'), HALF);
    }, HALF);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [current, reduced]);

  useEffect(() => () => window.clearTimeout(timer.current), []);

  useIsomorphicLayoutEffect(() => {
    if (moved.current) heading.current?.focus();
  }, [shown]);

  const view = views.find((v) => v.id === shown) ?? views[0];
  return (
    <div className={`mg-curtain ${className}`}>
      <nav className='mg-curtain__nav' aria-label={label}>
        {views.map((v) => (
          <button
            key={v.id}
            type='button'
            aria-current={v.id === current ? 'page' : undefined}
            onClick={() => onNavigate(v.id)}
          >
            {v.title}
          </button>
        ))}
      </nav>
      <div className='mg-curtain__stage'>
        <section className='mg-curtain__view' aria-labelledby={titleId}>
          <h3 id={titleId} ref={heading} tabIndex={-1}>
            {view.title}
          </h3>
          {view.content}
        </section>
        <span
          className='mg-curtain__cloth'
          data-phase={phase}
          aria-hidden='true'
        />
      </div>
    </div>
  );
}

.mg-curtain {
  display: grid;
  gap: 8px;
  color: var(--mg-text, #ffffff);
}

.mg-curtain__nav {
  display: flex;
  gap: 6px;
}

.mg-curtain__nav button {
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid var(--mg-line-strong, #474747);
  border-radius: 8px;
  background: #121212;
  color: inherit;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.mg-curtain__nav button[aria-current='page'] {
  border-color: var(--mg-text, #ffffff);
  background: var(--mg-raised, #262626);
  color: #fff;
}

.mg-curtain__nav button:focus-visible {
  outline: 2px solid var(--mg-accent-text, #648aff);
  outline-offset: 2px;
}

.mg-curtain__stage {
  position: relative;
  min-height: 170px;
  overflow: hidden;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 12px;
  background: #121212;
}

.mg-curtain__view {
  padding: 14px;
  color: #b8b8b8;
}

.mg-curtain__view h3 {
  margin: 0 0 6px;
  color: var(--mg-text, #ffffff);
  font-size: 18px;
}

.mg-curtain__view h3:focus {
  outline: none;
}

.mg-curtain__view h3:focus-visible {
  text-decoration: underline;
  text-decoration-color: var(--mg-accent-text, #648aff);
  text-underline-offset: 4px;
}

/* Draws in from the left to cover, then away to the right to reveal. */
.mg-curtain__cloth {
  position: absolute;
  inset: 0;
  background: var(--mg-accent, #0047ff);
  transform: scaleX(0);
  transform-origin: left;
  pointer-events: none;
}

.mg-curtain__cloth[data-phase='cover'] {
  transform: scaleX(1);
  transition: transform 220ms cubic-bezier(0.7, 0, 0.3, 1);
}

.mg-curtain__cloth[data-phase='reveal'] {
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 220ms cubic-bezier(0.7, 0, 0.3, 1);
}

@media (prefers-reduced-motion: reduce) {
  .mg-curtain__cloth {
    display: none;
  }
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
